cmn_relative_duration.script:
var due = new GlideDateTime(calculator.startDateTime);
if (current.scheduled_end && !current.scheduled_end.nil()) {
    due = new GlideDateTime(current.scheduled_end.getValue());
}
due.addSeconds(86400);
if (!due.after(calculator.startDateTime)) {
    due = new GlideDateTime(calculator.startDateTime);
    due.addSeconds(86400);
}
calculator.endDateTime = due;
calculator.calcScheduleDuration(calculator.startDateTime, due);
